# Circuit breaker implementation from scratch
class CircuitBreaker:
    CLOSED, OPEN, HALF_OPEN = 'CLOSED', 'OPEN', 'HALF_OPEN'

    def __init__(self, failure_threshold=1):
        self.state = self.CLOSED
        self._failures = 0
        self._threshold = failure_threshold

    def call(self, fn, *args, **kwargs):
        if self.state == self.OPEN:
            raise RuntimeError('Circuit OPEN - call rejected (fast-fail)')
        try:
            result = fn(*args, **kwargs)
            self._on_success()
            return result
        except Exception as exc:
            self._on_failure()
            raise

    def _on_success(self):
        if self.state == self.HALF_OPEN:
            self.state = self.CLOSED
            self._failures = 0
            print('  Circuit -> CLOSED (recovered)')

    def _on_failure(self):
        self._failures += 1
        if self.state == self.HALF_OPEN or self._failures >= self._threshold:
            self.state = self.OPEN
            print(f'  Circuit -> OPEN  (failures={self._failures})')

    def allow_probe(self):
        if self.state == self.OPEN:
            self.state = self.HALF_OPEN
            print('  Circuit -> HALF_OPEN (probe allowed)')

cb = CircuitBreaker(failure_threshold=1)
def flaky(should_fail):
    if should_fail: raise IOError('Service unavailable')
    return 'OK'

for fail in [False, True, True]:
    try: print(f'Call result: {cb.call(flaky, fail)}')
    except Exception as e: print(f'Call error:  {e}')

cb.allow_probe()
try: print(f'Probe result: {cb.call(flaky, False)}')
except Exception as e: print(f'Probe error: {e}')
